class MathBrainClient:
    def __init__(
        self, 
        host: str = "localhost", 
        port: int = 8080,
        chunk_size: int = 2000, 
        overlap: int = 200,
        # batch_size: int = 100    
    ) -> None:
        self.client = weaviate.connect_to_local(host=host, port=port)
        self.CHUNK_SIZE = chunk_size
        self.OVERLAP = overlap
        # self.BATCH_SIZE = batch_size


