@patch
def _display_summary(
        self: MathBrainSearcher,
        count: int,
        duration: float):
    print(f"\nFound {count} matches in {duration:.3f} seconds.")
    print("=" * 60)

@patch
def _display_results(
        self: MathBrainSearcher,
        objects):
    if not objects:
        print("No matches found.")
        return
    for i, obj in enumerate(objects):
        self._print_single_object(i + 1, obj)

